      this.ticket_modal.hide();
      this.data = {};

      this.add_ticket_resolution_modal.show();
    },

    addTicket() {
      console.log("step 151 :", this.data);

      this.http.post("tickets", this.data).then((res) => {
        if (res.status) this.get(this.page);
        this.add_or_edit_modal.hide();
      });
    },
    editTicket() {
      console.log("step 151 :", this.data.customer.name);
      if (!this.data?.customer_id && !this.data.customer?.name) {
        return this.popup.alert({
          title: "popups.error",
          msg: "popups.you_need_to_enter_customer_name",
        });
      } else {
        this.http.put("tickets", this.data.id, this.data).then((res) => {
