    },
    search(page) {
      if (!this.searchModel.length) return this.cancelappsearchMode();
      this.TicketsSearchMode = true;
      this.tot_pages = 0;
      this.http
        .post("tickets/search", {
          search: this.searchModel,
          col: "name",
          limit: this.limit,
          page: this.page,
        })
        .then((res) => {
          this.page = page;
          this.tot_pages = Math.ceil(res.tot / this.limit);
          this.tickets = res.data;
          // console.log('g' );
          // this.tickets = res.data.map(element =>
          // this.tickets = element.tickets,
          // console.log("xxxxxxx",this.tickets)).filter(z=>this.tickets = z.tickets)

