        });
    },
    cancelappsearchMode() {
      this.searchModel = "";
      this.TicketsSearchMode = false;
      this.get(this.page);
    },

    gitIssue() {
      this.http.get("issue-types").then((res) => {
        this.issues = res.data;
      });
    },
    gitcustomer() {
      this.http.get("customers").then((res) => {
        this.customers = res.data;
      });
    },
    deleteTickets(searchIn) {
      this.popup
        .confirm({
          title: "popups.delete",
          msg: "popups.delmessage",
        })
        .then((resp) => {
          if (resp) {
            this.http.delete("tickets", searchIn.id).then(() => {
              this.get(this.page);
            });
          }
        });
    },

    get(page) {
      console.log(page);
      this.http
        .post("tickets/pagination", {
          limit: this.limit,
          page: page,
        })
        .then((res) => {
          this.page = page;
          this.tot_pages = Math.ceil(res.tot / this.limit);
          this.tickets = res.data;
        });
    },
    preAddTicket() {
      this.editMode = false;

      this.data = {};
      this.add_or_edit_modal.show();
    },
    preEditTicket(record) {
      this.editMode = true;
      console.log(record);

      this.data = JSON.parse(JSON.stringify(record));
      this.add_or_edit_modal.show();
    },
    searchEmployees(search) {
      this.http
        .post(
          "emp-custodies/search-emps",
          {
            search,
            limit: 25,
            // current_emp_id: this.data.under_custody[0]?.emp_id,
          },
          null,
          true
        )
        .then((res) => {
          if (res.status) {
            this.emps = res.data;
          }
        });
    },
    searchCustomers(search) {
      this.http
        .post(
          "customers/search",
          {
            search,
            page: 1,
            limit: 25,
            // current_emp_id: this.data.under_custody[0]?.emp_id,
          },
          null,
          true
        )
        .then((res) => {
          if (res.status) {
            this.customers = res.data;
          }
        });
    },
    showEmpLabel(one) {
      return `${one.id} - ${one.name}`;
    },
    closeAddTicketModel() {
      this.add_or_edit_modal.hide();
    },
  },

  created() {
    this.get(1);

    this.gitIssue();
    // this.gitcustomer();
  },
  mounted() {
    this.add_or_edit_modal = new Modal("#addOrEditModal");
  },
};
</script>

<template>
  <Layout>
    <PageHeader
      :dir="$i18n.locale == 'ar' ? 'rtl' : 'ltr'"
      :title="$t('menu.menuitems.tickets.text')"
    />

    <!-- Start search box -->
    <div class="row">
      <div class="col-6">
        <div class="search-box chat-search-box w-50">
          <div class="position-relative">
            <input
              @input="search(page)"
              type="search"
              class="form-control fa-lg text-light"
              :dir="$i18n.locale == 'ar' ? 'rtl' : 'ltr'"
              :placeholder="$t('popups.search')"
              v-model="searchModel"
              style="background-color: #2a3042 !important"
            />
            <i class="bx bx-search-alt search-icon text-light"></i>
          </div>
        </div>
      </div>
      <div class="col-6" style="display: flex; justify-content: flex-end">
        <button
          type="button"
          @click="preAddTicket()"
          class="btn btn-light float-end mb-4"
        >
          <span
            class="bx bxs-plus-circle float-end fa-2x"
            style="color: #2a3042 !important"
          ></span>
        </button>
      </div>
    </div>
    <!-- end search box -->

    <table :dir="$i18n.locale == 'ar' ? 'rtl' : 'ltr'" class="table">
      <thead>
        <tr
          class="text-light text-center"
          style="background-color: #2a3042 !important"
        >
          <th scope="col">#</th>
          <th scope="col">{{ $t("tickets.id") }}</th>
          <th scope="col">{{ $t("tickets.issuetype") }}</th>
          <th scope="col">{{ $t("tickets.customer") }}</th>
          <th scope="col">{{ $t("tickets.description") }}</th>
          <th scope="col">{{ $t("tickets.status") }}</th>
          <th scope="col">{{ $t("tickets.priority") }}</th>
          <th scope="col" style="width: 2%">{{ $t("tickets.created") }}</th>

          <th scope="col">{{ $t("tickets.operations") }}</th>
        </tr>
      </thead>
      <tbody>
        <tr
          v-for="(searchIn, index) in tickets"
          :key="searchIn"
          class="text-center"
        >
          <td>{{ index + 1 }}</td>
          <td>{{ searchIn.id }}</td>
          <td>{{ searchIn.issue_type?.name }}</td>
          <td>
            {{
              searchIn?.customer?.name
                ? searchIn?.customer?.name
                : searchIn.customer_name
            }}
          </td>
          <td v-html="searchIn.description"></td>
          <td>
            <h6 v-if="!searchIn.status" class="text-danger">
              {{ $t("popups.underprogress") }}
            </h6>
            <span v-else class="text-success">{{ $t("popups.Finished") }}</span>
          </td>
          <td>
            <h6 v-if="searchIn.priority == 1" class="text-danger">
              {{ $t("popups.high") }}
            </h6>
            <span v-if="searchIn.priority == 2" class="text-warning">{{
              $t("popups.medium")
            }}</span>
            <h6 v-if="searchIn.priority == 3" class="text-success">
              {{ $t("popups.low") }}
            </h6>
          </td>
          <td>{{ searchIn?.created.split("T")[0] }}</td>

          <td class="d-flex justify-content-center">
            <button
              v-if="searchIn.remark === 0"
              @click="getSwitch(searchIn, 2)"
              class="btn btn-danger btn-sm me-2 mt-2"
            >
              {{ $t("popups.rejected") }}
            </button>
            <button
              v-if="searchIn.remark === 0"
              type="button"
              @click="getSwitch(searchIn, 1)"
              class="btn btn-success btn-sm me-2 mt-2"
            >
              {{ $t("popups.accepted") }}
            </button>
            <!-- <a
              class="btn btn-primary me-2"
              
              role="button"
              @click="gitresolution(searchIn)"
              >{{ $t("popups.resolutions") }}
            </a> -->
            <div v-if="searchIn.remark === 1">
              <button
                v-if="!searchIn.status"
                type="button"
                @click="closeTicket(searchIn)"
                class="btn btn-primary me-2"
              >
                {{ $t("popups.close_ticket") }}
              </button>
              <router-link
                class="btn btn-primary me-2"
                :to="{ name: 'ticketResolutions', params: { id: searchIn.id } }"
                role="button"
                >{{ $t("popups.resolutions") }}
              </router-link>
              <a
                class="btn btn-primary mt-1 me-2"
                @click="preEditTicket(searchIn)"
                href="javascript: void(0);"
                role="button"
                >{{ $t("popups.edit") }}</a
              >
              <a
