            <div class="modal-body">
              <div class="row">
                <div class="col-12 mb-3">
                  <label for="" class="form-label">{{
                    $t("popups.issuetype")
                  }}</label>
                  <select
                    class="form-select form-select-lg"
                    v-model="data.issue_type_id"
