                  <div class="mb-2">
                    <div class="form-check form-check-inline">
                      <input
                        class="form-check-input"
                        type="radio"
                        id="existingCustomer"
                        value="existing"
                        v-model="customerMode"
                      />
                      <label class="form-check-label" for="existingCustomer">{{
                        $t("popups.existingCustomer")
                      }}</label>
                    </div>
                    <div class="form-check form-check-inline">
                      <input
                        class="form-check-input"
                        type="radio"
                        id="newCustomer"
                        value="new"
                        v-model="customerMode"
                      />
                      <label class="form-check-label" for="newCustomer">{{
                        $t("popups.newCustomer")
                      }}</label>
                    </div>
                  </div>

                  <!-- AutoComplete for existing customer -->
                  <AutoComplete
                    v-if="customerMode === 'existing'"
                    required
                    v-model="data.customer"
                    :suggestions="customers"
                    @complete="searchCustomers($event.query)"
                    @item-select="data.customer_id = data.customer?.id"
                    :complete-on-focus="false"
                    :optionLabel="showEmpLabel"
                    :inputClass="'form-control'"
                    class="w-100"
                  />

                  <!-- Manual input for new customer -->
                  <input
                    v-if="customerMode === 'new'"
                    type="text"
                    class="form-control"
                    placeholder="Enter customer name"
                    v-model="newCustomerName"
                    @input="data.customer = { id: null, name: newCustomerName }"
                  />
                </div>
                <div class="col-12 mb-3">
                  <label for="" class="form-label">{{
                    $t("popups.priority")
                  }}</label>
                  <select
                    class="form-select form-select-lg"
                    v-model="data.priority"
                    required
                  >
                    <option value="1">{{ $t("popups.high") }}</option>
                    <option value="2">{{ $t("popups.medium") }}</option>
                    <option value="3">{{ $t("popups.low") }}</option>
                  </select>
                </div>

                <div class="col-12 mb-3">
                  <label for="" class="form-label">{{
                    $t("popups.des")
                  }}</label>
                  <ckeditor
                    :editor="editor"
                    v-model="data.description"
                    :config="editorConfig"
                  ></ckeditor>
                </div>
              </div>
            </div>
            <div class="modal-footer">
              <button type="submit" class="btn btn-primary">
                {{ editMode ? $t("popups.edit") : $t("popups.add") }}
              </button>
              <button
                type="button"
                class="btn btn-secondary"
                data-dismiss="modal"
                @click="closeAddTicketModel()"
              >
                {{ $t("popups.colse") }}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  </Layout>
</template>
